package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.material.*;
import net.minecraft.world.phys.*;
/** Actual native state containers and engine voxel unions, independent of any public registration. */
@net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs")
public final class ScreenBlockChecks {
 @net.neoforged.bus.api.SubscribeEvent public static void start(net.neoforged.neoforge.event.server.ServerStartedEvent event)throws Exception{if(!System.getProperty("vandorlabs.transmitterPhase","").startsWith("screen-block"))return;if(System.getProperty("vandorlabs.transmitterPhase").equals("screen-block-rows"))ScreenRowEditChecks.run(event.getServer().overworld(),BLOCKS);else run(event.getServer().overworld());event.getServer().halt(false);}
 private static final java.util.Map<ScreenFamily,NativeScreenBlock> BLOCKS=new java.util.EnumMap<>(ScreenFamily.class);private static BlockEntityType<NativeScreenEntity> TYPE;static java.util.function.Consumer<NativeScreenEntity> changedObserver;
 private static final class ObservedHost extends NativeScreenEntity {ObservedHost(BlockPos pos,BlockState state){super(TYPE,pos,state,((NativeScreenBlock)state.getBlock()).family(),NativeScreenCatalog.INSTANCE);}@Override public void setChanged(){if(visual()!=null&&visual().settings()!=screenSettings())throw new AssertionError("Incoherent Screen publication");var observer=changedObserver;if(observer!=null)observer.accept(this);super.setChanged();}}
 @net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs",bus=net.neoforged.fml.common.EventBusSubscriber.Bus.MOD)public static final class Registration {
  @net.neoforged.bus.api.SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!System.getProperty("vandorlabs.transmitterPhase","").startsWith("screen-block"))return;event.register(net.minecraft.core.registries.Registries.BLOCK,helper->{for(ScreenFamily family:ScreenFamily.values()){NativeScreenBlock block=NativeScreenBlock.create(family,BlockBehaviour.Properties.of(),()->TYPE);BLOCKS.put(family,block);helper.register(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vandorlabs","screen_block_fixture_"+family.name().toLowerCase(java.util.Locale.ROOT)),block);}});event.register(net.minecraft.core.registries.Registries.BLOCK_ENTITY_TYPE,helper->{TYPE=BlockEntityType.Builder.<NativeScreenEntity>of(ObservedHost::new,BLOCKS.values().toArray(Block[]::new)).build(null);helper.register(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vandorlabs","screen_block_fixture"),TYPE);});}
 }
 private static final class View implements BlockGetter {NativeScreenEntity tile;BlockState state;public BlockEntity getBlockEntity(BlockPos pos){if(!pos.equals(BlockPos.ZERO))throw new AssertionError("Nonlocal geometry read");return tile;}public BlockState getBlockState(BlockPos pos){return pos.equals(BlockPos.ZERO)?state:Blocks.AIR.defaultBlockState();}public FluidState getFluidState(BlockPos pos){return Fluids.EMPTY.defaultFluidState();}public int getHeight(){return 384;}public int getMinBuildHeight(){return -64;}}
 @SuppressWarnings("unchecked") private static void run(net.minecraft.server.level.ServerLevel world)throws Exception{
  java.util.Map<ScreenFamily,NativeScreenBlock> blocks=new java.util.EnumMap<>(ScreenFamily.class);java.util.Map<ScreenFamily,BlockEntityType<NativeScreenEntity>> types=new java.util.EnumMap<>(ScreenFamily.class);int states=0;
  for(ScreenFamily family:ScreenFamily.values()){NativeScreenBlock block=BLOCKS.get(family);blocks.put(family,block);types.put(family,TYPE);if(block.getStateDefinition().getPossibleStates().size()!=family.stateCount())throw new AssertionError("Native state domain "+family);for(BlockState state:block.getStateDefinition().getPossibleStates()){if(block.state(block.screenState(state))!=state||state.getRenderShape()!=RenderShape.MODEL)throw new AssertionError("State mapping/render pipeline");states++;}}
  JsonObject source;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenGeometryReference")))){source=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0,samples=0;
  for(var entry:source.getAsJsonArray("cases")){var expected=entry.getAsJsonObject();ScreenFamily family=ScreenFamily.fromId(expected.get("id").getAsString());NativeScreenBlock block=blocks.get(family);View view=new View();view.state=block.state(family.decode(expected.get("meta").getAsInt()));view.tile=new NativeScreenEntity(types.get(family),BlockPos.ZERO,view.state,family,NativeScreenCatalog.INSTANCE);CompoundTag settings=new CompoundTag();settings.putBoolean("smallInput",expected.get("small").getAsBoolean());int wall=expected.get("wall").getAsInt(),ceiling=expected.get("ceiling").getAsInt();if(wall>=0)settings.putInt("wallPosition",wall);settings.putBoolean("CeilingMounted",ceiling>=0);if(ceiling>=0)settings.putInt("CeilingPosition",ceiling);view.tile.loadWithComponents(settings,RegistryAccess.EMPTY);AABB bounds=block.geometry(view.state,view,BlockPos.ZERO).bounds();compare(bounds,expected.getAsJsonArray("bounds"));var actual=view.state.getCollisionShape(view,BlockPos.ZERO).toAabbs();JsonArray boxes=expected.getAsJsonArray("collision");for(double x:new double[]{-.25,.125,.375,.625,.875,1.25})for(double y:new double[]{-.25,.125,.375,.625,.875,1.25})for(double z:new double[]{-.25,.125,.375,.625,.875,1.25}){boolean wanted=false,found=false;for(var box:boxes){var b=box.getAsJsonArray();if(x>=b.get(0).getAsDouble()&&x<b.get(3).getAsDouble()&&y>=b.get(1).getAsDouble()&&y<b.get(4).getAsDouble()&&z>=b.get(2).getAsDouble()&&z<b.get(5).getAsDouble())wanted=true;}for(AABB b:actual)if(b.contains(x,y,z))found=true;if(wanted!=found)throw new AssertionError("Native engine collision differs "+family+" at="+x+","+y+","+z);samples++;}cases++;}
  overhang(world,blocks.get(ScreenFamily.HALF_CONSOLE));ScreenRowEditChecks.run(world,blocks);
  if(states!=70||cases!=2240)throw new AssertionError("Coverage");System.out.println("Native Screen block foundation PASS states="+states+" sourceGeometry="+cases+" engineCollisionSamples="+samples+" unregistered; configured item mounting/player routing remain separate");
 }
 private static void overhang(net.minecraft.server.level.ServerLevel world,NativeScreenBlock block){BlockPos root=new BlockPos(4200,90,4200);world.getChunkAt(root);for(BlockPos at:BlockPos.betweenClosed(root.offset(-2,-1,-2),root.offset(2,2,3)))world.setBlock(at,Blocks.AIR.defaultBlockState(),2);world.setBlock(root,block.defaultBlockState(),2);NativeScreenEntity owner=(NativeScreenEntity)world.getBlockEntity(root);CompoundTag settings=new CompoundTag();settings.putBoolean("CeilingMounted",true);settings.putInt("CeilingPosition",2);owner.loadWithComponents(settings,world.registryAccess());AABB query=new AABB(root.getX()+.2,root.getY()+.1,root.getZ()+1.1,root.getX()+.8,root.getY()+.4,root.getZ()+1.4);if(!world.getBlockCollisions(null,query).iterator().hasNext())throw new AssertionError("Actual Level collision query lost half-console overhang outside owner voxel");world.setBlock(root,Blocks.AIR.defaultBlockState(),2);if(world.getBlockCollisions(null,query).iterator().hasNext())throw new AssertionError("Overhang query retained missing owner");System.out.println("Native Screen actual Level outside-owner collision query PASS");}
 private static void compare(AABB actual,JsonArray expected){double[] values={actual.minX,actual.minY,actual.minZ,actual.maxX,actual.maxY,actual.maxZ};for(int i=0;i<6;i++)if(Math.abs(values[i]-expected.get(i).getAsDouble())>1e-12)throw new AssertionError("Block geometry differs "+actual+" source="+expected);}
}
